// Define variables
var width = 500;
var height = 500;
var cornerRadius = 20;

// Calculate control points for each segment
function getControlPoints(x1, y1, x2, y2, r) {
    var dx = x2 - x1;
    var dy = y2 - y1;
    var d = Math.sqrt(dx * dx + dy * dy);
    if (d < r) return [x1, y1, x2, y2]; // If distance is less than radius, no need to calculate controls

    var angle = Math.atan2(dy, dx);
    var cx1 = x1 + r * Math.cos(angle - Math.PI / 2);
    var cy1 = y1 + r * Math.sin(angle - Math.PI / 2);
    var cx2 = x2 - r * Math.cos(angle + Math.PI / 2);
    var cy2 = y2 - r * Math.sin(angle + Math.PI / 2);

    return [cx1, cy1, cx2, cy2];
}

// Get control points for all segments
var topLeft = getControlPoints(0, 0, cornerRadius, cornerRadius, cornerRadius);
var topRight = getControlPoints(width - cornerRadius, 0, width, 0, cornerRadius);
var bottomRight = getControlPoints(width, height - cornerRadius, width, height, cornerRadius);
var bottomLeft = getControlPoints(cornerRadius, height, 0, height, cornerRadius);

// Combine into one path
