using DocumentFormat.OpenXml.Wordprocessing;
using System;
using System.Collections.Generic;
using System.Linq;

public class WordMerger
{
    public static void MergeDocuments(string sourceDocPath1, string sourceDocPath2, string outputDocPath)
    {
        // Load the first document
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDocPath1, false))
        {
            MainDocumentPart mainPart1 = doc1.MainDocumentPart;
            Body body1 = mainPart1.Document.Body;

            // Extract header, footer, and style information
            HeaderPart headerPart1 = null;
            FooterPart footerPart1 = null;
            StylesPart stylesPart1 = null;

            if (mainPart1.HeaderParts.Any())
                headerPart1 = mainPart1.HeaderParts.First();
            if (mainPart1.FooterParts.Any())
                footerPart1 = mainPart1.FooterParts.First();
            if (mainPart1.StyleDefinitionsPart != null && mainPart1.StyleDefinitionsPart.Styles != null)
                stylesPart1 = mainPart1.StyleDefinitionsPart;

            // Create a new document for merging
            using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(outputDocPath, WordprocessingDocumentType.Document))
            {
                MainDocumentPart mainPartMerged = mergedDoc.AddMainDocumentPart();
                mainPartMerged.Document = new Document(new Body());

                // Add header and footer if they exist
                if (headerPart1 != null)
                {
                    HeaderPart headerPartMerged = mainPartMerged.AddNewPart<HeaderPart>();
                    headerPartMerged.Header = headerPart1.Header.CloneNode(true);
                }

                if (footerPart1 != null)
                {
                    FooterPart footerPartMerged = mainPartMerged.AddNewPart<FooterPart>();
                    footerPartMerged.Footer = footerPart1.Footer.CloneNode(true);
                }

                // Add styles if they exist
                if (stylesPart1 != null)
                {
                    StylesPart stylesPartMerged = mainPartMerged.AddNewPart<StylesPart>();
                    stylesPartMerged.Styles = stylesPart1.Styles.CloneNode(true);
                }

                // Process the first two pages of the first document
                int pageCount = 0;
                foreach (var paragraph in body1.Elements<Paragraph>())
                {
                    if (++pageCount > 2) break;

                    Paragraph p = new Paragraph(paragraph.CloneNode(true));
                    mainPartMerged.Document.Body.Append(p);

                    // Handle runs within paragraphs
                    foreach (var run in paragraph.Elements<Run>())
                    {
                        Run r = new Run(run.CloneNode(true));
                        p.Append(r);
                    }
                }

                // Load the second document
                using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDocPath2, false))
                {
                    MainDocumentPart mainPart2 = doc2.MainDocumentPart;
                    Body body2 = mainPart2.Document.Body;

                    // Copy content from the second document
                    foreach (var element in body2.Elements())
                    {
                        if (!(element is Header || element is Footer || element is Footnote || element is Endnote ||
                              element is CommentRangeStart || element is CommentRangeEnd || element is CommentReference))
                        {
                            var clonedElement = element.CloneNode(true);
                            mainPartMerged.Document.Body.Append(clonedElement);
                        }
                    }
                }
            }
        }
    }
}
```

