```gdscript
# ChunkManager.gd
extends Node3D

const CHUNK_SIZE = 16

var chunks = {} # Dictionary to store chunks by their coordinates

func create_chunk(x: int, y: int, z: int) -> Spatial:
    var chunk = Spatial.new()
    chunk.name = "Chunk_" + str(x) + "_" + str(y) + "_" + str(z)

    for i in range(CHUNK_SIZE):
        for j in range(CHUNK_SIZE):
            for k in range(CHUNK_SIZE):
                var voxel = preload("res://Voxel.tscn").instance()
                voxel.set_position(Vector3(i, j, k))
                chunk.add_child(voxel)

    chunks[(x, y, z)] = chunk
    add_child(chunk)
    return chunk

func get_chunk(x: int, y: int, z: int) -> Spatial:
    if (x, y, z) in chunks:
        return chunks[(x, y, z)]
    else:
        return create_chunk(x, y, z)

func generate_terrain() -> void:
