public class ListChecker {

    public static <T> T getSingleEntryOrThrow(List<T> list) {
        // Check if the list is empty and return null
        if (list.isEmpty()) {
            return null;
        }

        // Use stream to count entries in the list
        long count = list.stream().count();

        // If there's more than one entry, throw an exception
        if (count > 1) {
            throw new IllegalStateException("List contains more than one entry.");
        }

        // Return the single entry or null if the list was empty
        return list.get(0);
    }

