        try {
            String result = getSingleEntryOrThrow(exampleList);
            System.out.println(result); // Output: single
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }

        List<String> multiEntryList = List.of("one", "two");
        try {
            String result = getSingleEntryOrThrow(multiEntryList);
            System.out.println(result);
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage()); // Output: List contains more than one entry.
        }

        List<String> emptyList = List.of();
        String result = getSingleEntryOrThrow(emptyList);
        System.out.println(result); // Output: null
    }
}
```

