#include <stdio.h>
#include <stdlib.h>

#define REVERB_SIZE 1024 // Size of the delay line

typedef struct {
    float buffer[REVERB_SIZE];
    int writeIndex;
} Reverb;

void initReverb(Reverb *reverb) {
    memset(reverb->buffer, 0, sizeof(float) * REVERB_SIZE);
    reverb->writeIndex = 0;
}

float processSample(Reverb *reverb, float sample) {
    static const float feedback = 0.5f; // Feedback gain
    static const float wetGain = 0.7f;   // Wet signal gain
    static const float dryGain = 0.3f;   // Dry signal gain

    float delayedSample = reverb->buffer[(reverb->writeIndex + REVERB_SIZE / 2) % REVERB_SIZE];

    float output = wetGain * (sample + feedback * delayedSample) +
                   dryGain * sample;

    reverb->buffer[reverb->writeIndex] = sample;
    reverb->writeIndex = (reverb->writeIndex + 1) % REVERB_SIZE;

    return output;
}
```

