{
    /**
     * Add a favorite name for a user.
     *
     * @param string $name The name to add to the favorites list.
     * @param User|null $user The authenticated user (if any).
     */
    public function addFavorite(string $name, ?User $user = null): void
    {
        if ($user) {
            // Save the favorite to the database for the authenticated user.
            Favorite::create([
                'user_id' => $user->id,
                'name' => $name,
            ]);
        } else {
            // Save the favorite to the session for the guest user.
            session()->push('favorites', $name);
        }
    }

    /**
     * Remove a favorite name from the list.
     *
     * @param string $name The name to remove from the favorites list.
     * @param User|null $user The authenticated user (if any).
     */
    public function removeFavorite(string $name, ?User $user = null): void
    {
        if ($user) {
            // Delete the favorite from the database for the authenticated user.
            Favorite::where('user_id', $user->id)
                ->where('name', $name)
                ->delete();
        } else {
            // Remove the favorite from the session for the guest user.
            session()->forget('favorites.' . array_search($name, session('favorites')));
        }
    }

    /**
     * Get all favorite names for a user.
     *
     * @param User|null $user The authenticated user (if any).
     * @return array An array of favorite names.
     */
    public function getFavorites(?User $user = null): array
    {
        if ($user) {
            // Retrieve the favorites from the database for the authenticated user.
            return Favorite::where('user_id', $user->id)->pluck('name')->toArray();
        } else {
