```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredsToken is ERC1155, Ownable {
    // Event to log when a new credential type is added
    event CredentialTypeAdded(uint256 indexed id);

    // Mapping from credential ID to metadata URI
    mapping(uint256 => string) private _credentialMetadata;

    constructor() ERC1155("") {}

    /**
     * @dev Mints a specified amount of a given credential type to a recipient.
     * @param to The address receiving the minted tokens.
     * @param id The ID of the credential type being minted.
     * @param amount The number of tokens to mint.
     */
    function mintCred(
        address to,
        uint256 id,
        uint256 amount
    ) external onlyOwner {
        _mint(to, id, amount, "");
        emit CredentialTypeAdded(id);
    }

    /**
     * @dev Sets the metadata URI for a specific credential type.
     * @param id The ID of the credential type.
     * @param uri The URI pointing to the metadata JSON file.
     */
    function setCredentialMetadata(
        uint256 id,
        string memory uri
    ) external onlyOwner {
        _credentialMetadata[id] = uri;
    }

    /**
     * @dev Returns the metadata URI for a specific credential type.
     * @param id The ID of the credential type.
     * @return The URI pointing to the metadata JSON file.
     */
    function getCredentialMetadata(
        uint256 id
    ) public view returns (string memory) {
        return _credentialMetadata[id];
    }
}
```

