Here's a simple implementation that extracts information such as source port, destination port, sequence number, acknowledgment number, flags, window size, checksum, and urgent pointer:

```typescript
interface TcpHeader {
  sourcePort: number;
  destinationPort: number;
  sequenceNumber: number;
  acknowledgementNumber: number;
  dataOffset: number; // The first byte indicates the length of the header (in 32-bit words)
  reserved: number;
  flags: {
    fin: boolean;
    syn: boolean;
    rst: boolean;
    psh: boolean;
    ack: boolean;
    urg: boolean;
    ece: boolean;
    cwr: boolean;
  };
  windowSize: number;
  checksum: number;
  urgentPointer: number;
}

function parseTcpHeader(data: Uint8Array): TcpHeader {
  const tcpHeader = new DataView(data.buffer, data.byteOffset);

  const sourcePort = tcpHeader.getUint16(0);
  const destinationPort = tcpHeader.getUint16(2);
  const sequenceNumber = tcpHeader.getUint32(4);
  const acknowledgementNumber = tcpHeader.getUint32(8);

  let dataOffset = (tcpHeader.getUint8(12) >> 4) * 4;

  const reserved = tcpHeader.getUint8(12) & 0x0F;
  const flags = {
    fin: !!(tcpHeader.getUint8(13) & 0x01),
    syn: !!(tcpHeader.getUint8(13) & 0x02),
    rst: !!(tcpHeader.getUint8(13) & 0x04),
    psh: !!(tcpHeader.getUint8(13) & 0x08),
    ack: !!(tcpHeader.getUint8(13) & 0x10),
    urg: !!(tcpHeader.getUint8(13) & 0x20),
    ece: !!(tcpHeader.getUint8(13) & 0x40),
    cwr: !!(tcpHeader.getUint8(13) & 0x80),
  };

  const windowSize = tcpHeader.getUint16(14);
  const checksum = tcpHeader.getUint16(16);
  const urgentPointer = tcpHeader.getUint16(18);

  return {
    sourcePort,
    destinationPort,
    sequenceNumber,
    acknowledgementNumber,
    dataOffset,
    reserved,
    flags,
    windowSize,
    checksum,
    urgentPointer,
  };
}

// Example usage:
const buffer = new Uint8Array([
  0x50, 0x50, // Source Port
  0x50, 0x50, // Destination Port
  0x00, 0x00, 0x00, 0x00, // Sequence Number
  0x00, 0x00, 0x00, 0x00, // Acknowledgment Number
  0x50, 0x00, // Data Offset and Reserved
  0x00, // Flags
  0x00, 0x00, // Window Size
  0x00, 0x00, // Checksum
  0x00, 0x00, // Urgent Pointer
]);

const parsedTcpHeader = parseTcpHeader(buffer);
console.log(parsedTcpHeader);
```

This code snippet provides a function `parseTcpHeader` that takes a `Uint8Array` representing the raw TCP header bytes and returns an object containing the parsed fields. Note that this does not handle the actual processing or reassembly of TCP segments into higher-level protocols like HTTP or FTP.

