```metal
#include <metal_stdlib>
using namespace metal;

// Define the size of the Gaussian kernel (must be odd)
const int KERNEL_SIZE = 5;
const float SIGMA = 1.0f; // Standard deviation

// Function to calculate the Gaussian weight based on distance from center
float gaussianWeight(int x, int y) {
    float dx = abs(x - KERNEL_SIZE / 2);
    float dy = abs(y - KERNEL_SIZE / 2);
    return exp(-(dx * dx + dy * dy) / (2.0f * SIGMA * SIGMA));
}

kernel void gaussianBlur(texture2d<float, access::read> inputTexture [[texture(0)]],
                         texture2d<float, access::write> outputTexture [[texture(1)]],
                         uint2 gid [[thread_position_in_grid]]) {

    // Calculate the sum of weights and the weighted average for each pixel
    float4 sum = float4(0.0f);
    float totalWeight = 0.0f;

    for (int i = -KERNEL_SIZE / 2; i <= KERNEL_SIZE / 2; ++i) {
        for (int j = -KERNEL_SIZE / 2; j <= KERNEL_SIZE / 2; ++j) {
            int x = gid.x + i;
            int y = gid.y + j;

            if (x >= 0 && x < inputTexture.get_width() &&
                y >= 0 && y < inputTexture.get_height()) {
                float weight = gaussianWeight(i, j);
                sum += inputTexture.read(make_int2(x, y)) * weight;
                totalWeight += weight;
            }
        }
    }

    // Write the blurred pixel value to the output texture
    outputTexture.write(sum / totalWeight, gid);
}
```

