```typescript
class RNN {
  private weights: number[][];
  private biases: number[];

  constructor(inputSize: number, hiddenSize: number, outputSize: number) {
    this.weights = [
      // Input-to-hidden weights
      Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1),
      // Hidden-to-hidden weights
      Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1),
      // Hidden-to-output weights
      Array.from({ length: outputSize }, () => Math.random() * 2 - 1)
    ];

    this.biases = [
      // Input-to-hidden bias
      Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1),
      // Hidden-to-hidden bias
      Array.from({ length: hiddenSize }, () => Math.random() * 2 - 1),
      // Hidden-to-output bias
      Array.from({ length: outputSize }, () => Math.random() * 2 - 1)
    ];
  }

  public forward(input: number[]): number[] {
    const [hiddenWeights, hiddenToHiddenWeights, outputWeights] = this.weights;
    const [inputBias, hiddenBias, outputBias] = this.biases;

    let hiddenState = input.map((value, index) => value * hiddenWeights[index]) as number[];
    hiddenState = hiddenState.map((value, index) => value + hiddenBias[index]);
    hiddenState = hiddenState.map(Math.tanh);

    const output = hiddenState.map((value, index) => value * outputWeights[index]) as number[];
    output.forEach((value, index) => (output[index] += outputBias[index]));

    return output;
  }
}

