import random

def fisher_yates_shuffle(sequence):
    # Create a copy of the original sequence to avoid modifying it directly
    shuffled_sequence = list(sequence)

    # Perform the Fisher-Yates shuffle
    for i in range(len(shuffled_sequence) - 1, 0, -1):
        j = random.randint(0, i)
        shuffled_sequence[i], shuffled_sequence[j] = shuffled_sequence[j], shuffled_sequence[i]

    return shuffled_sequence

# Example usage:
