template<typename Iterator>
void fisher_yates_shuffle(Iterator begin, Iterator end) {
    static_assert(std::is_same_v<std::iterator_traits<Iterator>::value_type, int>, "Only supports integer types");

    std::random_device rd;  // Obtain a random number from hardware
